data.query:
query IntegrationConfiguration($where: IntegrationConfigurationWhereInput, $whereIS: IntegrationStagingWhereInput) 
{
  integrationConfiguration(
    where: $where
  ) {
    edges {
      node {
        id
        name
        active
        isInbound
        integrationTypeId
        requestHandlerDataFlowId
        integrationDataFlowId
        responseDataFlowId
        autoRetryResponses
        lastTransactionAt
        latestRecordId
        savedScriptId
        maxRecords
        parameters
      }
    }
  }
  integrationStaging(
    where: $whereIS
  ) {
    edges {
      node {
        id
      }
    }
  }
}

data.responseTransform:
{
  "success": true,
  "message": "Outbound request received successfully, record added for processing queue."
}

{
  "success": false,
  "message": "The setup is not configured in the integration tenant for the provided record type"
}

